  'tool3-con2' => 'Որոշ առանձնահատկություններ պահանջում են վճարովի պլան:',
  'tool3-con3' => 'Ամփոփումները կարող են բաց թողնել բարդ ձևաչափման նշանները:',
  'tool4-heading' => 'Adobe Acrobat AI Summarizer',
  'tool4-para' => 'Adobe-ի AI ամփոփիչն իր առցանց փաստաթղթերի գործիքների մի մասն է: Այն օգտագործում է Adobe-ի գեներատիվ AI՝ ուրվագծելու և ընդգծելու հիմնական փաստաթղթերի բաժինները: Գործիքը աջակցում է բազմաթիվ ձևաչափերի, ստեղծում է ընթեռնելի ամփոփագրեր և կարող է հղում կատարել PDF-ի բնօրինակ բովանդակությանը:',
  'tool4-pro1' => 'Ուժեղ ինտեգրում Adobe-ի փաստաթղթերի էկոհամակարգի հետ:',
  'tool4-pro2' => 'Հստակ, կառուցվածքային ամփոփումներ՝ աղբյուրի հղումներով:',
  'tool4-pro3' => 'Անվտանգության և գաղտնիության վստահելի չափանիշներ:',
  'tool4-con1' => 'Պահանջում է Adobe հաշիվ և երբեմն բաժանորդագրություն:',
  'tool4-con2' => 'Անհատականացման ավելի քիչ տարբերակներ, քան որոշ մրցակիցներ:',
  'tool4-con3' => 'Անվճար օգտագործումը կարող է սահմանափակվել հարցումների սահմանաչափերով:',
